    /** 更换链与重算版本只读查询：全部工时表（含 offset 与最后有效读数）、更换记录、recalcVersion。 */
    @GetMapping("/{equipmentId}/meter-chain")
    public MeterChainResponse getMeterChain(@PathVariable String equipmentId) {
        return service.getMeterChain(equipmentId);
    }
}

