        long lastVirtual = JsonPath.read(body, "$.meters[0].lastVirtualHours");
        long offset = JsonPath.read(body, "$.meters[1].offsetHours");
        long initialRaw = JsonPath.read(body, "$.meters[1].initialRawHours");
        assertEquals(lastVirtual - initialRaw, offset, "冻结 offset 必须等于前驱最后有效虚拟工时减去新表起始读数");
